import{_ as e,o as t,c as i,ag as n}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-10-09（生物医学）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/biomedicine/science-daily-2026-10-09.md","filePath":"topics/biomedicine/science-daily-2026-10-09.md"}'),s={name:"topics/biomedicine/science-daily-2026-10-09.md"};function r(c,o,a,l,d,g){return t(),i("div",null,[...o[0]||(o[0]=[n('<h1 id="科学日报-·-2026-10-09-生物医学" tabindex="-1">科学日报 · 2026-10-09（生物医学） <a class="header-anchor" href="#科学日报-·-2026-10-09-生物医学" aria-label="Permalink to &quot;科学日报 · 2026-10-09（生物医学）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-09.md</code> — 第32期</p></blockquote><hr><h2 id="rna-催化从动态结构系综中涌现-而非来自单一静态结构-nature" tabindex="-1">RNA 催化从动态结构系综中涌现，而非来自单一静态结构（Nature） <a class="header-anchor" href="#rna-催化从动态结构系综中涌现-而非来自单一静态结构-nature" aria-label="Permalink to &quot;RNA 催化从动态结构系综中涌现，而非来自单一静态结构（Nature）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-09.md</code> ｜ DOI: 10.1038/s41586-026-11140-z</p></blockquote><ul><li>背景：RNA 结构与其结合 <strong>Mg²⁺ 离子</strong>的动态相互作用对 RNA 功能至关重要，但此前在<strong>近原子尺度</strong>上认识不足（柔性 RNA 颗粒的构象异质性难解析）。</li><li>方法：采用<strong>面向异质性的冷冻电镜数据处理方案</strong>，解析 RNase P RNA 系综——<strong>76 个共存的活性/非活性构象</strong>，它们在一个对活性至关重要的<strong>瞬态三级相互作用</strong>上各不相同。</li><li>结果：辅助蛋白结合<strong>不改变局部结构</strong>，而是通过改变该三级相互作用的<strong>动力学</strong>诱导热力学变构、增强催化；四类功能不同的 Mg²⁺ 离子在系综的结构/动力学/催化中起关键作用。</li><li>结论：确立新范式——<strong>催化由 RNA–Mg²⁺ 构象系综的多模态耦合动力学调控</strong>，而不是某个单一静态催化结构在单一作用模式下完成。</li><li>洞察：又一个&quot;<strong>功能不是静态结构，而是动态系综的统计属性</strong>&quot;的实例。与本库量子物理侧反复出现的&quot;测量/维护动作必须能与被保护态共存&quot;、以及 AI 侧&quot;缓存/风味&quot;等母题同构：<strong>真正的对象是分布，不是样本</strong>。</li></ul><h2 id="肠道微生物组-启动-了疫苗接种后的发热-science" tabindex="-1">肠道微生物组&quot;启动&quot;了疫苗接种后的发热（Science） <a class="header-anchor" href="#肠道微生物组-启动-了疫苗接种后的发热-science" aria-label="Permalink to &quot;肠道微生物组&quot;启动&quot;了疫苗接种后的发热（Science）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-09.md</code> ｜ DOI: 10.1126/science.aea7733</p></blockquote><ul><li>问题：发热是接种疫苗的常见不良反应，会加剧<strong>疫苗犹豫</strong>、降低接种率；其个体差异来源不清。</li><li>方法：对 <strong>171 名</strong>接种 SARS-CoV-2 mRNA 疫苗的健康成人做<strong>纵向</strong>粪便菌群 + 口腔温度 + 血清标志物检测。</li><li>数据：发热风险与<strong>低度肠道炎症</strong>、带鞭毛的 <strong>Lachnospiraceae</strong> 细菌丰度升高、以及<strong>接种前鞭毛蛋白表达</strong>升高相关；&quot;高发热&quot;供体菌群在<strong>人肠道类器官</strong>中触发更强炎症，并在<strong>无菌小鼠</strong>中驱动依赖鞭毛蛋白的疫苗反应。</li><li>可干预性：菌群鞭毛蛋白表型与小鼠疫苗反应<strong>可被饮食改变</strong>；人的发热风险也与自报饮食和代谢标志物相关。</li><li>意义：把肠道微生物组确认为<strong>疫苗诱导发热的驱动因素</strong>，提示可通过调控菌群调节免疫基调、改善疫苗不良反应。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/biomedicine/index.md</code> ｜ 第32期 科学板块</p></blockquote><p>关键词：RNA 催化、RNase P、构象系综、Mg²⁺、冷冻电镜、热力学变构、动态结构；疫苗发热、肠道微生物组、鞭毛蛋白、Lachnospiraceae、mRNA 疫苗、无菌小鼠、类器官 关联：<code>topics/biomedicine/science-daily-2026-10-08.md</code>（同日延续的肠道微生物主线：Tsimane×Hadza 共享 1231 物种）、<code>topics/neuroscience/index.md</code>（该主题标注&quot;肠道-大脑轴&quot;为<strong>未覆盖</strong>方向——本篇补上&quot;菌群→免疫基调&quot;的第一条实物证据）、<code>topics/physics/science-daily-2026-10-08.md</code>（跨主题母题：静态对象 vs 动态分布）</p>',12)])])}const q=e(s,[["render",r]]);export{p as __pageData,q as default};
